L24:  | // A Reader reads the Go benchmark format.
L25:  | //
L26:  | // Its API is modeled on bufio.Scanner. To minimize allocation, a
L27:  | // Reader retains ownership of everything it creates; a caller should
L28:  | // copy anything it needs to retain.
L29:  | //
L30:  | // To construct a new Reader, either call NewReader, or call Reset on
L31:  | // a zeroed Reader.
L32:  | type Reader struct {
L33:  | s *bufio.Scanner
L34:  | err error // current I/O error
L35:  |
L36:  | // q is the queue of records to return before processing the next
L37:  | // input line. qPos is the index of the current record in q. We
L38:  | // track the index explicitly rather than slicing q so that we can
L39:  | // reuse the q slice when we reach the end.
L40:  | q []Record
L41:  | qPos int
L42:  |
L43:  | result Result
L44:  | units UnitMetadataMap
L45:  |
L46:  | interns map[string]string
L47:  | }
L48:  |
L49:  | // A SyntaxError represents a syntax error on a particular line of a
L50:  | // benchmark results file.
L51:  | type SyntaxError struct {
L52:  | FileName string
L53:  | Line int
L54:  | Msg string
L55:  | }
L56:  |
L57:  | func (e *SyntaxError) Pos() (fileName string, line int) {
L58:  | return e.FileName, e.Line
L59:  | }
L60:  |
L61:  | func (s *SyntaxError) Error() string {
L62:  | return fmt.Sprintf("%s:%d: %s", s.FileName, s.Line, s.Msg)
L63:  | }
L64:  |
L65:  | var noResult = &SyntaxError{"", 0, "Reader.Scan has not been called"}
L66:  | var errSkip = &SyntaxError{"", 0, "skip line"}
L67:  |
L68:  | // NewReader constructs a reader to parse the Go benchmark format from r.
L69:  | // fileName is used in error messages; it is purely diagnostic.
L70:  | func NewReader(r io.Reader, fileName string) *Reader {
L71:  | reader := new(Reader)
L72:  | reader.Reset(r, fileName)
L73:  | return reader
L74:  | }
L75:  |
L76:  | // newSyntaxError returns a *SyntaxError at the Reader's current position.
L77:  | func (r *Reader) newSyntaxError(msg string) *SyntaxError {
L78:  | return &SyntaxError{r.result.fileName, r.result.line, msg}
L79:  | }
L80:  |
L81:  | // Reset resets the reader to begin reading from a new input.
L82:  | // It also resets all accumulated configuration values.
L83:  | // It does NOT reset unit metadata because it carries across files.
L84:  | //
L85:  | // initConfig is an alternating sequence of keys and values.
L86:  | // Reset will install these as the initial internal configuration
L87:  | // before any results are read from the input file.
L88:  | func (r *Reader) Reset(ior io.Reader, fileName string, initConfig ...string) {
L89:  | r.s = bufio.NewScanner(ior)
L90:  | if fileName == "" {
L91:  | fileName = "<unknown>"
L92:  | }
L93:  | r.err = nil
L94:  | if r.interns == nil {
L95:  | r.interns = make(map[string]string)
L96:  | }
L97:  | if r.units == nil {
L98:  | r.units = make(map[UnitMetadataKey]*UnitMetadata)
L99:  | }
L100:  |
L101:  | // Wipe the queue in case the user hasn't consumed everything from
L102:  | // this file.
L103:  | r.qPos = 0
L104:  | r.q = r.q[:0]
L105:  |
L106:  | // Wipe the Result.
L107:  | r.result.Config = r.result.Config[:0]
L108:  | r.result.Name = r.result.Name[:0]
L109:  | r.result.Iters = 0
L110:  | r.result.Values = r.result.Values[:0]
L111:  | for k := range r.result.configPos {
L112:  | delete(r.result.configPos, k)
L113:  | }
L114:  | r.result.fileName = fileName
L115:  | r.result.line = 0
L116:  |
L117:  | // Set up initial configuration.
L118:  | if len(initConfig)%2 != 0 {
L119:  | panic("len(initConfig) must be a multiple of 2")
L120:  | }
L121:  | for i := 0; i < len(initConfig); i += 2 {
L122:  | r.result.SetConfig(initConfig[i], initConfig[i+1])
L123:  | }
L124:  | }
L125:  |
L126:  | var (
L127:  | benchmarkPrefix = []byte("Benchmark")
L128:  | unitPrefix = []byte("Unit")
L129:  | )
L130:  |
L131:  | // Scan advances the reader to the next result and reports whether a
L132:  | // result was read.
L133:  | // The caller should use the Result method to get the result.
L134:  | // If Scan reaches EOF or an I/O error occurs, it returns false,
L135:  | // in which case the caller should use the Err method to check for errors.
L136:  | func (r *Reader) Scan() bool {
L137:  | if r.err != nil {
L138:  | return false
L139:  | }
L140:  |
L141:  | // If there's anything in the queue from an earlier line, just pop
L142:  | // the queue and return without consuming any more input.
L143:  | if r.qPos+1 < len(r.q) {
L144:  | r.qPos++
L145:  | return true
L146:  | }
L147:  | // Otherwise, we've drained the queue and need to parse more input
L148:  | // to refill it. Reset it to 0 so we can reuse the space.
L149:  | r.qPos = 0
L150:  | r.q = r.q[:0]
L151:  |
L152:  | // Process lines until we add something to the queue or hit EOF.
L153:  | for len(r.q) == 0 && r.s.Scan() {
L154:  | r.result.line++
L155:  | // We do everything in byte buffers to avoid allocation.
L156:  | line := r.s.Bytes()
L157:  | // Most lines are benchmark lines, and we can check
L158:  | // for that very quickly, so start with that.
L159:  | if bytes.HasPrefix(line, benchmarkPrefix) {
L160:  | if err := r.parseBenchmarkLine(line); err == nil {
L161:  | r.q = append(r.q, &r.result)
L162:  | } else if err != errSkip {
L163:  | r.q = append(r.q, err)
L164:  | }
L165:  | continue
L166:  | }
L167:  | if len(line) > 0 && line[0] == 'U' {
L168:  | if nLine, ok := r.isUnitLine(line); ok {
L169:  | // Parse unit metadata line. This queues up its own
L170:  | // records and errors.
L171:  | r.parseUnitLine(nLine)
L172:  | continue
L173:  | }
L174:  | }
L175:  | if key, val, ok := parseKeyValueLine(line); ok {
L176:  | // Intern key, since there tend to be few
L177:  | // unique keys.
L178:  | keyStr := r.intern(key)
L179:  | if len(val) == 0 {
L180:  | r.result.deleteConfig(keyStr)
L181:  | } else {
L182:  | cfg := r.result.ensureConfig(keyStr, true)
L183:  | cfg.Value = append(cfg.Value[:0], val...)
L184:  | }
L185:  | continue
L186:  | }
L187:  | // Ignore the line.
L188:  | }
L189:  |
L190:  | if len(r.q) > 0 {
L191:  | // We queued something up to return.
L192:  | return true
L193:  | }
L194:  |
L195:  | // We hit EOF. Check for IO errors.
L196:  | if err := r.s.Err(); err != nil {
L197:  | r.err = fmt.Errorf("%s:%d: %w", r.result.fileName, r.result.line, err)
L198:  | return false
L199:  | }
L200:  | r.err = nil
L201:  | return false
L202:  | }
L203:  |
L204:  | // parseKeyValueLine attempts to parse line as a key: val pair,
L205:  | // with ok reporting whether the line could be parsed.
L206:  | func parseKeyValueLine(line []byte) (key, val []byte, ok bool) {
L207:  | for i := 0; i < len(line); {
L208:  | r, n := utf8.DecodeRune(line[i:])
L209:  | // key begins with a lower case character ...
L210:  | if i == 0 && !unicode.IsLower(r) {
L211:  | return
L212:  | }
L213:  | // and contains no space characters nor upper case
L214:  | // characters.
L215:  | if unicode.IsSpace(r) || unicode.IsUpper(r) {
L216:  | return
L217:  | }
L218:  | if i > 0 && r == ':' {
L219:  | key, val = line[:i], line[i+1:]
L220:  | break
L221:  | }
L222:  |
L223:  | i += n
L224:  | }
L225:  | if len(key) == 0 {
L226:  | return
L227:  | }
L228:  | // Value can be omitted entirely, in which case the colon must
L229:  | // still be present, but need not be followed by a space.
L230:  | if len(val) == 0 {
L231:  | ok = true
L232:  | return
L233:  | }
L234:  | // One or more ASCII space or tab characters separate "key:"
L235:  | // from "value."
L236:  | for len(val) > 0 && (val[0] == ' ' || val[0] == '\t') {
L237:  | val = val[1:]
L238:  | ok = true
L239:  | }
L240:  | return
L241:  | }
L242:  |
L243:  | // parseBenchmarkLine parses line as a benchmark result and updates r.result.
L244:  | // The caller must have already checked that line begins with "Benchmark".
L245:  | func (r *Reader) parseBenchmarkLine(line []byte) *SyntaxError {
L246:  | var f []byte
L247:  | var err error
L248:  |
L249:  | // Skip "Benchmark"
L250:  | line = line[len("Benchmark"):]
L251:  |
L252:  | // Read the name.
L253:  | lineLen := len(line)
L254:  | r.result.Name, line = splitField(line)
L255:  |
L256:  | // As a special case, if the name is the entire line, we
L257:  | // ignore it. This happens in "go test -v" output, which
L258:  | // prints the benchmark name immediately followed by a newline
L259:  | // when the benchmark starts.
L260:  | if len(line) == 0 && len(r.result.Name) == lineLen {
L261:  | return errSkip
L262:  | }
L263:  |
L264:  | // Read the iteration count.
L265:  | f, line = splitField(line)
L266:  | if len(f) == 0 {
L267:  | return r.newSyntaxError("missing iteration count")
L268:  | }
L269:  | r.result.Iters, err = bytesconv.Atoi(f)
L270:  | switch err := err.(type) {
L271:  | case nil:
L272:  | // ok
L273:  | case *bytesconv.NumError:
L274:  | return r.newSyntaxError("parsing iteration count: " + err.Err.Error())
L275:  | default:
L276:  | return r.newSyntaxError(err.Error())
L277:  | }
L278:  |
L279:  | // Read value/unit pairs.
L280:  | r.result.Values = r.result.Values[:0]
L281:  | for {
L282:  | f, line = splitField(line)
L283:  | if len(f) == 0 {
L284:  | if len(r.result.Values) > 0 {
L285:  | break
L286:  | }
L287:  | return r.newSyntaxError("missing measurements")
L288:  | }
L289:  | val, err := atof(f)
L290:  | switch err := err.(type) {
L291:  | case nil:
L292:  | // ok
L293:  | case *bytesconv.NumError:
L294:  | return r.newSyntaxError("parsing measurement: " + err.Err.Error())
L295:  | default:
L296:  | return r.newSyntaxError(err.Error())
L297:  | }
L298:  | f, line = splitField(line)
L299:  | if len(f) == 0 {
L300:  | return r.newSyntaxError("missing units")
L301:  | }
L302:  | unit := r.intern(f)
L303:  |
L304:  | // Tidy the value.
L305:  | tidyVal, tidyUnit := benchunit.Tidy(val, unit)
L306:  | var v Value
L307:  | if tidyVal == val {
L308:  | v = Value{Value: val, Unit: unit}
L309:  | } else {
L310:  | v = Value{Value: tidyVal, Unit: tidyUnit, OrigValue: val, OrigUnit: unit}
L311:  | }
L312:  |
L313:  | r.result.Values = append(r.result.Values, v)
L314:  | }
L315:  |
L316:  | return nil
L317:  | }
L318:  |
L319:  | // isUnitLine tests whether line is a unit metadata line. If it is, it
L320:  | // returns the line after the "Unit" literal and true.
L321:  | func (r *Reader) isUnitLine(line []byte) (rest []byte, ok bool) {
L322:  | var f []byte
L323:  | // Is this a unit metadata line?
L324:  | f, line = splitField(line)
L325:  | if bytes.Equal(f, unitPrefix) {
L326:  | return line, true
L327:  | }
L328:  | return nil, false
L329:  | }
L330:  |
L331:  | // parseUnitLine parses line as a unit metadata line, starting
L332:  | // after "Unit". It updates r.q.
L333:  | // If there are syntax errors on the line, it will attempt to parse
L334:  | // what it can and return a non-nil error.
L335:  | func (r *Reader) parseUnitLine(line []byte) {
L336:  | var f []byte
L337:  | // isUnitLine already consumed the literal "Unit".
L338:  | // Consume the next field, which is the unit.
L339:  | f, line = splitField(line)
L340:  | if len(f) == 0 {
L341:  | r.q = append(r.q, r.newSyntaxError("missing unit"))
L342:  | return
L343:  | }
L344:  | unit := r.intern(f)
L345:  |
L346:  | // The metadata map is indexed by tidied units because we want to
L347:  | // support lookups by tidy units and there's no way to "untidy" a
L348:  | // unit.
L349:  | _, tidyUnit := benchunit.Tidy(1, unit)
L350:  |
L351:  | // Consume key=value pairs.
L352:  | for {
L353:  | f, line = splitField(line)
L354:  | if len(f) == 0 {
L355:  | break
L356:  | }
L357:  | eq := bytes.IndexByte(f, '=')
L358:  | if eq <= 0 {
L359:  | r.q = append(r.q, r.newSyntaxError("expected key=value"))
L360:  | continue
L361:  | }
L362:  | key := UnitMetadataKey{tidyUnit, r.intern(f[:eq])}
L363:  | value := r.intern(f[eq+1:])
L364:  |
L365:  | if have, ok := r.units[key]; ok {
L366:  | if have.Value == value {
L367:  | // We already have this unit metadata. Ignore.
L368:  | continue
L369:  | }
L370:  | // Report incompatible unit metadata.
L371:  | r.q = append(r.q, r.newSyntaxError(fmt.Sprintf("metadata %s of unit %s already set to %s", key.Key, unit, have.Value)))
L372:  | continue
L373:  | }
L374:  |
L375:  | metadata := &UnitMetadata{key, unit, value, r.result.fileName, r.result.line}
L376:  | r.units[key] = metadata
L377:  | r.q = append(r.q, metadata)
L378:  | }
L379:  | }
L380:  |
L381:  | func (r *Reader) intern(x []byte) string {
L382:  | const maxIntern = 1024
L383:  | if s, ok := r.interns[string(x)]; ok {
L384:  | return s
L385:  | }
L386:  | if len(r.interns) >= maxIntern {
L387:  | // Evict a random item from the interns table.
L388:  | // Map iteration order is unspecified, but both
L389:  | // the gc and libgo runtimes both provide random
L390:  | // iteration order. The choice of item to evict doesn't
L391:  | // affect correctness, so we do the simple thing.
L392:  | for k := range r.interns {
L393:  | delete(r.interns, k)
L394:  | break
L395:  | }
L396:  | }
L397:  | s := string(x)
L398:  | r.interns[s] = s
L399:  | return s
L400:  | }
L401:  |
L402:  | // A Record is a single record read from a benchmark file. It may be a
L403:  | // *Result or a *SyntaxError.
L404:  | type Record interface {
L405:  | // Pos returns the position of this record as a file name and a
L406:  | // 1-based line number within that file. If this record was not read
L407:  | // from a file, it returns "", 0.
L408:  | Pos() (fileName string, line int)
L409:  | }
L410:  |
L411:  | var _ Record = (*Result)(nil)
L412:  | var _ Record = (*SyntaxError)(nil)
L413:  | var _ Record = (*UnitMetadata)(nil)
L414:  |
L415:  | // Result returns the record that was just read by Scan. This is either
L416:  | // a *Result, a *UnitMetadata, or a *SyntaxError indicating a parse error.
L417:  | // It may return more types in the future.
L418:  | //
L419:  | // Parse errors are non-fatal, so the caller can continue to call
L420:  | // Scan.
L421:  | //
L422:  | // If this returns a *Result, the caller should not retain the Result,
L423:  | // as it will be overwritten by the next call to Scan.
L424:  | func (r *Reader) Result() Record {
L425:  | if r.qPos >= len(r.q) {
L426:  | // This should only happen if Scan has never been called.
L427:  | return noResult
L428:  | }
L429:  | return r.q[r.qPos]
L430:  | }
L431:  |
L432:  | // Err returns the first non-EOF I/O error that was encountered by the
L433:  | // Reader.
L434:  | func (r *Reader) Err() error {
L435:  | return r.err
L436:  | }
L437:  |
L438:  | // Units returns the accumulated unit metadata.
L439:  | //
L440:  | // Callers that want to consume the entire stream of benchmark results
L441:  | // and then process units can use this instead of monitoring
L442:  | // *UnitMetadata Records.
L443:  | func (r *Reader) Units() UnitMetadataMap {
L444:  | return r.units
L445:  | }
L446:  |
L447:  | // Parsing helpers.
L448:  | //
L449:  | // These are designed to leverage common fast paths. The ASCII fast
L450:  | // path is especially important, and more than doubles the performance
L451:  | // of the parser.
L452:  |
L453:  | // atof is a wrapper for bytesconv.ParseFloat that optimizes for
L454:  | // numbers that are usually integers.
L455:  | func atof(x []byte) (float64, error) {
L456:  | // Try parsing as an integer.
L457:  | var val int64
L458:  | for _, ch := range x {
L459:  | digit := ch - '0'
L460:  | if digit >= 10 {
L461:  | goto fail
L462:  | }
L463:  | if val > (math.MaxInt64-10)/10 {
L464:  | goto fail // avoid int64 overflow
L465:  | }
L466:  | val = (val * 10) + int64(digit)
L467:  | }
L468:  | return float64(val), nil
L469:  |
L470:  | fail:
L471:  | // The fast path failed. Parse it as a float.
L472:  | return bytesconv.ParseFloat(x, 64)
L473:  | }
L474:  |
L475:  | const isSpace uint64 = 1<<'\t' | 1<<'\n' | 1<<'\v' | 1<<'\f' | 1<<'\r' | 1<<' '
L476:  |
L477:  | // splitField consumes and returns non-whitespace in x as field,
L478:  | // consumes whitespace following the field, and then returns the
L479:  | // remaining bytes of x.
L480:  | func splitField(x []byte) (field, rest []byte) {
L481:  | // Collect non-whitespace into field.
L482:  | var i int
L483:  | for i = 0; i < len(x); {
L484:  | if x[i] < utf8.RuneSelf {
L485:  | // Fast path for ASCII
L486:  | if (isSpace>>x[i])&1 != 0 {
L487:  | rest = x[i+1:]
L488:  | break
L489:  |
L490:  | }
L491:  | i++
L492:  | } else {
L493:  | // Slow path for Unicode
L494:  | r, n := utf8.DecodeRune(x[i:])
L495:  | if unicode.IsSpace(r) {
L496:  | rest = x[i+n:]
L497:  | break
L498:  | }
L499:  | i += n
L500:  | }
L501:  | }
L502:  | field = x[:i]
L503:  |
L504:  | // Strip whitespace from rest.
L505:  | for len(rest) > 0 {
L506:  | if rest[0] < utf8.RuneSelf {
L507:  | if (isSpace>>rest[0])&1 == 0 {
L508:  | break
L509:  | }
L510:  | rest = rest[1:]
L511:  | } else {
L512:  | r, n := utf8.DecodeRune(rest)
L513:  | if !unicode.IsSpace(r) {
L514:  | break
L515:  | }
L516:  | rest = rest[n:]
L517:  | }
L518:  | }
L519:  | return
L520:  | }
